package ru.bububu.radio.sources;

import org.junit.Test;
import java.nio.charset.StandardCharsets;
import static org.junit.Assert.*;

public class SourceSemanticAdaptersTest {
    static RequestScope scope(){return new RequestScope(1,1);}
    static SourceTransport.Response html(String url,String content){return new SourceTransport.Response(("<!doctype html><html><head><title>Fixture</title></head><body>"+content+"</body></html>").getBytes(StandardCharsets.UTF_8),url,200,"text/html","UTF-8",null,null);}
    static String interfax(String body){return "<article itemprop='articleBody'><h1 itemprop='headline'>Заголовок</h1>"+body+"</article>";}
    static String ria(String body){return "<div class='article__title'>Заголовок</div><div class='article__body'>"+body+"</div>";}
    static String riaText(String text){return "<div class='article__block' data-type='text'><div class='article__text'>"+text+"</div></div>";}
    @Test public void shortInterfaxFullAndBrLinkBoundaries()throws Exception {ExtractionResult result=new InterfaxArticleAdapter().extract(html("https://www.interfax.ru/world/123",interfax("<p>Коротко.<br>Следующая <a href='/world/456'>строка</a>.</p>")),scope());assertEquals("full",result.completeness);assertEquals("Коротко.\nСледующая строка.",result.body);assertTrue(result.extractedTextNodes>0);assertEquals(0,result.unknownTextNodes);}
    @Test public void unknownInterfaxWrapperAndLooseTextCannotPass()throws Exception {for(String body:new String[]{"<p>Известное.</p><div>Новый блок.</div><p>Конец.</p>","Текст между блоками.<p>Известное.</p>"}){ExtractionResult result=new InterfaxArticleAdapter().extract(html("https://www.interfax.ru/world/123",interfax(body)),scope());assertEquals("unknown",result.completeness);assertEquals("UNSUPPORTED_STRUCTURE",result.reason);assertTrue(result.unknownTextNodes>0);}}
    @Test public void mutatedFigureNeverExcludedByClass()throws Exception {String image="<figure class='inner'><img itemprop='image' src='https://images.test/x'><figcaption class='innerTable'><div class='author'>Фотограф</div><p>Новый важный текст.</p></figcaption></figure>";ExtractionResult result=new InterfaxArticleAdapter().extract(html("https://www.interfax.ru/world/123",interfax("<p>Новость.</p>"+image)),scope());assertEquals("unknown",result.completeness);assertTrue(result.body.contains("Новый важный текст."));}
    @Test public void verifiedFigureAndUpdateExcludeExactlyKnownShapes()throws Exception {String image="<figure class='inner'><img itemprop='image'><figcaption class='innerTable'><div class='author'>Фотограф</div></figcaption></figure>";String update="<aside class='textMUpdate'><div>Есть обновление от 18:45<span>→</span></div><div><a href='/world/456'>Другая публикация</a></div></aside>";ExtractionResult result=new InterfaxArticleAdapter().extract(html("https://www.interfax.ru/world/123",interfax("<p>Новость.</p>"+image+update)),scope());assertEquals("full",result.completeness);assertEquals("Новость.",result.body);assertTrue(result.excludedTextNodes>=3);}
    @Test public void mutatedAsideCannotDiscardNewParagraph()throws Exception {String update="<aside class='textMUpdate'><div>Есть обновление от 18:45<span>→</span></div><div><a href='/world/456'>Другая публикация</a><p>Новая часть.</p></div></aside>";ExtractionResult result=new InterfaxArticleAdapter().extract(html("https://www.interfax.ru/world/123",interfax("<p>Новость.</p>"+update)),scope());assertEquals("unknown",result.completeness);assertTrue(result.body.contains("Новая часть."));}
    @Test public void changedExclusionWithUnsafeLinkKeepsReadableBodyAsUnknown()throws Exception {String update="<aside class='textMUpdate'><div>Есть обновление от 18:45<span>→</span></div><div><a href='https://127.0.0.1/private'>Иная публикация</a></div></aside>";ExtractionResult result=new InterfaxArticleAdapter().extract(html("https://www.interfax.ru/world/123",interfax("<p>Оригинал.</p>"+update)),scope());assertEquals("unknown",result.completeness);assertTrue(result.body.contains("Оригинал."));assertEquals("UNSUPPORTED_STRUCTURE",result.reason);}
    @Test public void repairedBodyCannotClaimFull()throws Exception {ExtractionResult result=new InterfaxArticleAdapter().extract(html("https://www.interfax.ru/world/123",interfax("<p>Начало <a href='/x'>текст</p><p>Конец.</p>")),scope());assertEquals("unknown",result.completeness);}
    @Test public void unsupportedPublisherHostDoesNotInheritContract()throws Exception {ExtractionResult result=new InterfaxArticleAdapter().extract(html("https://sport-interfax.ru/news/123",interfax("<p>Текст.</p>")),scope());assertEquals("UNSUPPORTED_HOST",result.reason);assertNotEquals("full",result.completeness);}
    @Test public void riaTextFullWithStrongAndLink()throws Exception {ExtractionResult result=new RiaArticleAdapter().extract(html("https://ria.ru/20261012/story-123.html",ria(riaText("<strong>Спорт</strong>: <a href='/x'>слово</a>."))),scope());assertEquals("full",result.completeness);assertEquals("Спорт: слово.",result.body);}
    static String card(boolean marker){return "<div class='article__block' data-type='article' data-id='999' data-nosnippet='true'"+(marker?" data-ciad-suggested='1'":"")+"><div class='article__article'><div class='article__article-image'><img></div><span class='article__article-desc'><a class='article__article-title' href='https://ria.ru/20261010/other-456.html?in=t'>Другая новость</a><div class='article__article-info'><div class='article__block-date'>10 октября, 18:45</div><span class='share' data-nosnippet='true' data-id='456' data-url='https://ria.ru/20261010/other-456.html'></span></div></span><a class='article__article-link' href='https://ria.ru/20261010/other-456.html?in=t'></a></div></div>";}
    @Test public void riaBothSuggestionVariantsAndOpaqueOuterId()throws Exception {for(boolean marker:new boolean[]{true,false}){ExtractionResult result=new RiaArticleAdapter().extract(html("https://ria.ru/20261012/story-123.html",ria(riaText("Новость.")+card(marker))),scope());assertEquals("full",result.completeness);assertEquals("Новость.",result.body);assertTrue(result.excludedTextNodes>=2);}}
    @Test public void riaRsportAndNewListRemainUnknown()throws Exception {for(String extra:new String[]{"<div class='article__block' data-type='rsport'><div class='article__match'>Команда А 1:2 Команда Б</div></div>","<ul><li>Новая часть</li></ul>"}){ExtractionResult result=new RiaArticleAdapter().extract(html("https://ria.ru/20261012/story-123.html",ria(riaText("Новость.")+extra)),scope());assertEquals("unknown",result.completeness);}}
    @Test public void riaChangedAiSummaryInvalidatesFullButNeverAddsAiText()throws Exception {String summary="<div class='article__summary'><div class='new-form'>Текст ИИ</div></div>";ExtractionResult result=new RiaArticleAdapter().extract(html("https://ria.ru/20261012/story-123.html",ria(riaText("Оригинал.")+summary)),scope());assertEquals("unknown",result.completeness);assertEquals("Оригинал.",result.body);assertFalse(result.body.contains("Текст ИИ"));}
    @Test public void riaUnprovedExternalSecondTitleIsUnknown()throws Exception {ExtractionResult result=new RiaArticleAdapter().extract(html("https://ria.ru/20261012/story-123.html","<h1 class='article__second-title'>Иной заголовок</h1>"+ria(riaText("Оригинал."))),scope());assertEquals("unknown",result.completeness);assertEquals("UNSUPPORTED_LEAD",result.reason);}
    @Test public void semanticListsQuotesEntityAndLiteralWordsKept()throws Exception {String body=SemanticTextNormalizer.fromDom(DomBudgetGuard.parse("<p>Реклама &amp; Подробнее</p><ul><li>Один</li><li>Два</li></ul><blockquote>Цитата<br>Продолжение</blockquote><script>BAD</script><nav>MENU</nav>","https://source.test",scope()).document.body(),scope());assertEquals("Реклама & Подробнее\n\nОдин\n\nДва\n\nЦитата\nПродолжение",body);assertFalse(body.contains("BAD"));}
    @Test public void domDepthAndTokenClippingRejectBeforeExtraction()throws Exception {try{DomBudgetGuard.parse("<div>".repeat(600)+"important"+"</div>".repeat(600),"https://source.test",scope());fail();}catch(SourceFailure expected){assertEquals("DOM_LIMIT",expected.reason);}try{DomBudgetGuard.parse("<br>".repeat(50_001),"https://source.test",scope());fail();}catch(SourceFailure expected){assertEquals("HTML_TOKEN_LIMIT",expected.reason);}}
    @Test public void discoveryMultipleRelativeFeedsIgnoresJsonAndTextXml()throws Exception {String doc="<!doctype html><html><head><base href='https://source.test/news/'><link rel='alternate' type='application/rss+xml' href='../rss'><link rel='alternate' type='application/atom+xml' href='atom/' title='Atom 0.3'><link rel='alternate' type='application/json' href='/api'><link rel='alternate' type='text/xml' href='/rss-old'></head><body>BODY NOT FEED</body></html>";SourceTransport.Response response=new SourceTransport.Response(doc.getBytes(StandardCharsets.UTF_8),"https://source.test/home",200,"text/html","UTF-8",null,null);java.util.List<FeedDiscovery.Candidate> feeds=new FeedDiscovery().discover(response,scope());assertEquals(2,feeds.size());assertEquals("https://source.test/rss",feeds.get(0).url);assertEquals("https://source.test/news/atom/",feeds.get(1).url);}
    @Test public void discoveryConflictingBaseAndNoFeed()throws Exception {String conflict="<!doctype html><html><head><base href='https://a.test/'><base href='https://b.test/'></head><body></body></html>";SourceTransport.Response response=new SourceTransport.Response(conflict.getBytes(StandardCharsets.UTF_8),"https://source.test/",200,"text/html","UTF-8",null,null);SourcePolicyTest.assertFailure("CONFLICTING_BASE",()->new FeedDiscovery().discover(response,scope()));assertTrue(new FeedDiscovery().discover(html("https://source.test/","<p>No feed</p>"),scope()).isEmpty());}
    static String tg(String messages){return "<div class='tgme_channel_info_header_username'><a>@rbc_news</a></div><div class='tgme_channel_info_header_title'>РБК</div>"+messages;}
    static String post(String id,String body){return "<div class='tgme_widget_message' data-post='rbc_news/"+id+"'>"+body+"</div>";}
    @Test public void telegramOwnBodyExcludesReplyAndKeepsOwnQuote()throws Exception {String own="<a class='tgme_widget_message_reply'><div class='tgme_widget_message_text js-message_reply_text'>Старый текст</div></a><div class='tgme_widget_message_text js-message_text'>Первый<br>Второй<p>Абзац</p><blockquote>Своя цитата</blockquote><a href='https://outside.test'>ссылка</a></div>";FeedDocument document=new TelegramPreviewAdapter().parse(html("https://t.me/s/rbc_news",tg(post("1",own))),"rbc_news",scope());ExtractionResult result=document.items.get(0).inline;assertFalse(result.body.contains("Старый текст"));assertTrue(result.body.contains("Первый\nВторой"));assertTrue(result.body.contains("Своя цитата"));assertEquals("unknown",result.completeness);SourceArticleFramer.Framed frame=SourceArticleFramer.frame("РБК",result);assertEquals("РБК\n\n"+result.body,frame.spokenText);}
    @Test public void telegramUnsupportedAndMissingBodyNotEnqueued()throws Exception {FeedDocument document=new TelegramPreviewAdapter().parse(html("https://t.me/s/rbc_news",tg(post("1","<div class='message_media_not_supported_label'>Open Telegram</div>")+post("2","<div>Неизвестная форма</div>"))),"rbc_news",scope());for(FeedItem item:document.items){assertEquals(item.postId.equals("1")?"unsupported_web_preview":"NO_OWN_TEXT",item.inline.reason);assertFalse(item.inline.canEnqueue());}}
    @Test public void telegramPreviewOffersLatestPostsAcrossTheItemCap()throws Exception {
        String own="<div class='tgme_widget_message_text js-message_text'>Короткая публикация.</div>";
        StringBuilder page=new StringBuilder();
        for(int i=1;i<=SourceLimits.MAX_PARSED_ITEMS+1;i++)page.append(post(Integer.toString(i),own));
        String newest="18446744073709551616";
        page.append(post(newest, own));
        page.append(post("9", own)); // A repeated older post cannot displace a newer one.
        FeedDocument doc=new TelegramPreviewAdapter().parse(html("https://t.me/s/rbc_news",tg(page.toString())),"rbc_news",scope());
        assertTrue(doc.itemLimitReached);
        assertEquals(SourceLimits.MAX_PARSED_ITEMS,doc.items.size());
        assertEquals(newest,doc.items.get(0).postId);
        assertEquals(Integer.toString(SourceLimits.MAX_PARSED_ITEMS+1),doc.items.get(1).postId);
        assertEquals(Integer.toString(SourceLimits.MAX_PARSED_ITEMS),doc.items.get(2).postId);
        assertEquals("3",doc.items.get(doc.items.size()-1).postId);
        assertEquals("https://t.me/rbc_news/"+newest,doc.items.get(0).url);
        page.append(post("1", own.replace("Короткая","Другая")));
        SourcePolicyTest.assertFailure("TELEGRAM_CONFLICTING_POST", ()->new TelegramPreviewAdapter()
                .parse(html("https://t.me/s/rbc_news",tg(page.toString())),"rbc_news",scope()));
    }
    @Test public void telegramRefusesAmbiguousNumericPostIdentity()throws Exception {
        for(String id:new String[]{"0","01"})SourcePolicyTest.assertFailure("TELEGRAM_CHANNEL_MISMATCH",
                ()->new TelegramPreviewAdapter().parse(html("https://t.me/s/rbc_news",tg(post(id,""))),"rbc_news",scope()));
    }
    @Test public void telegramWrongChannelAndConflictingDuplicateFail()throws Exception {SourcePolicyTest.assertFailure("TELEGRAM_CHANNEL_MISMATCH",()->new TelegramPreviewAdapter().parse(html("https://t.me/s/rbc_news",tg("<div class='tgme_widget_message' data-post='other/1'></div>")),"rbc_news",scope()));String a="<div class='tgme_widget_message_text js-message_text'>Первый</div>",b="<div class='tgme_widget_message_text js-message_text'>Другой</div>";SourcePolicyTest.assertFailure("TELEGRAM_CONFLICTING_POST",()->new TelegramPreviewAdapter().parse(html("https://t.me/s/rbc_news",tg(post("1",a)+post("1",b))),"rbc_news",scope()));}
    @Test public void telegramInputIdentityNormalFormsAndPrivateRejects()throws Exception {for(String value:new String[]{"@Kommersant","https://t.me/kommersant","https://t.me/s/kommersant"})assertEquals("telegram_public:kommersant",TelegramPreviewAdapter.normalizeInput(value).sourceKey);for(String value:new String[]{"https://t.me/+invite","https://t.me/c/1","https://t.me/rbc_news/1","https://user@t.me/rbc_news","https://t.me/rbc_news?secret=1","https://t.me/rbc_news#x"})SourcePolicyTest.assertFailure("TELEGRAM_INPUT",()->TelegramPreviewAdapter.normalizeInput(value));}
    @Test public void framingPreservesExactBodyHashAndVersionFields()throws Exception {ExtractionResult result=new ExtractionResult("Тело.","Заголовок","Display","unknown","REASON","feed_inline","test-v1");SourceArticleFramer.Framed frame=SourceArticleFramer.frame("Источник",result);assertEquals(result.body,frame.spokenText.substring(frame.bodyStart,frame.bodyEnd));assertEquals(SourceLimits.snapshotVersion(result.bodyHash,result.providerTitle,"Источник",result.completeness,result.reason,result.adapterVersion,SemanticTextNormalizer.VERSION,SourceArticleFramer.VERSION),frame.versionHash);assertNotEquals(frame.versionHash,SourceArticleFramer.frame("Другой",result).versionHash);}
    @Test public void wholeFramedTwentyThousandLimitIncludesPrefix()throws Exception {ExtractionResult result=new ExtractionResult("а".repeat(SourceLimits.MAX_TEXT),"","","unknown","","feed_inline","test-v1");SourcePolicyTest.assertFailure("TEXT_LIMIT",()->SourceArticleFramer.frame("Источник",result));}
}
